INSERT INTO `questions` VALUES (38,8,'INVEST IN RELATIONSHIP','rating_scale',NULL,0,'2026-07-12 03:05:38','2026-07-12 03:11:48'),(39,8,'EMPATHY','rating_scale',NULL,1,'2026-07-12 03:05:48','2026-07-12 03:11:48'),(41,8,'PURSUE EXCELLENCE','rating_scale',NULL,2,'2026-07-12 03:12:03','2026-07-12 03:12:03'),(42,8,'ACCOUNTABLE','rating_scale',NULL,3,'2026-07-12 03:12:09','2026-07-12 03:12:09'),(43,8,'CAN DO ATTITUDE','rating_scale',NULL,4,'2026-07-12 03:12:16','2026-07-12 03:12:16'),(44,8,'TEAMWORK','rating_scale',NULL,5,'2026-07-12 03:12:21','2026-07-12 03:12:21'),(45,8,'Bagaimana Anda menilai performa dan kontribusi Anda selama periode ini? Sebutkan pencapaian, tantangan, serta area yang masih perlu ditingkatkan.','text',NULL,6,'2026-07-12 03:12:49','2026-07-12 03:12:49'),(46,8,'Apa aspirasi dan tujuan karier yang ingin Anda capai di perusahaan ini, serta target yang ingin Anda capai pada periode berikutnya?','text',NULL,7,'2026-07-12 03:13:01','2026-07-12 03:13:01'),(47,8,'Apa masukan atau saran yang ingin Anda berikan untuk meningkatkan kinerja, proses kerja, atau kolaborasi di divisi Anda?','text',NULL,8,'2026-07-12 03:13:12','2026-07-12 03:13:12'),(48,8,'Apa masukan, harapan, atau saran yang ingin Anda sampaikan kepada manajemen untuk mendukung perkembangan karyawan dan perusahaan?','text',NULL,9,'2026-07-12 03:13:20','2026-07-12 03:13:20'),(49,9,'Tuliskan aktifitas yang kamu dan rekanmu kerjakan bersama!\nAktifitas ini bisa saja bersifat jangka pendek atau panjang, selama itu adalah sesuatu yang kalian kolaborasikan. Aktifitas itu bisa berupa proyek, inisiatif, tugas bersama, dll.','text',NULL,0,'2026-07-12 03:24:48','2026-07-12 03:24:48'),(50,9,'INVEST IN RELATIONSHIP','rating_scale',NULL,1,'2026-07-12 03:25:03','2026-07-12 03:25:03'),(51,9,'EMPATHY','rating_scale',NULL,2,'2026-07-12 03:25:11','2026-07-12 03:25:11'),(52,9,'PURSUE EXCELLENCE','rating_scale',NULL,3,'2026-07-12 03:25:28','2026-07-12 03:25:28'),(54,9,'ACCOUNTABLE','rating_scale',NULL,4,'2026-07-12 03:25:38','2026-07-12 03:25:38'),(55,9,'CAN DO ATTITUDE','rating_scale',NULL,5,'2026-07-12 03:25:49','2026-07-12 03:25:49'),(56,9,'TEAMWORK','rating_scale',NULL,6,'2026-07-12 03:25:55','2026-07-12 03:25:55'),(57,9,'Apa kualitas atau kebiasaan positif yang kamu amati dari rekanmu selama bekerja dengan mereka?','text',NULL,7,'2026-07-12 03:26:05','2026-07-12 03:26:05'),(58,9,'Apakah kamu memiliki saran untuk rekanmu agar mereka dapat meningkatkan kerjasamanya dengan orang lain?','text',NULL,8,'2026-07-12 03:26:10','2026-07-12 03:26:10'),(59,10,'INVEST IN RELATIONSHIP','rating_scale',NULL,0,'2026-07-12 23:41:25','2026-07-12 23:41:25'),(60,10,'Emphaty','rating_scale',NULL,1,'2026-07-12 23:41:32','2026-07-12 23:41:32'),(61,10,'PURSUE EXCELLENCE','rating_scale',NULL,2,'2026-07-12 23:41:38','2026-07-12 23:41:38'),(62,10,'ACCOUNTABLE','rating_scale',NULL,3,'2026-07-12 23:41:51','2026-07-12 23:41:51'),(63,10,'CAN DO ATTITUDE','rating_scale',NULL,4,'2026-07-12 23:42:01','2026-07-12 23:42:01'),(64,10,'TEAMWORK','rating_scale',NULL,5,'2026-07-12 23:42:07','2026-07-12 23:42:07'),(65,10,'Apa kekuatan utama karyawan ini yang paling memberikan dampak positif bagi tim atau perusahaan?','text',NULL,6,'2026-07-12 23:42:16','2026-07-12 23:42:16'),(66,10,'Area pengembangan apa yang perlu menjadi fokus karyawan ini pada periode berikutnya?','text',NULL,7,'2026-07-12 23:42:27','2026-07-12 23:42:27'),(67,10,'Apa target atau ekspektasi utama yang Anda harapkan dapat dicapai oleh karyawan ini pada periode berikutnya?','text',NULL,8,'2026-07-13 00:12:14','2026-07-13 00:12:14'),(68,11,'Head saya mampu menetapkan tujuan, prioritas dan mendefinisikan kesuksesan tim.','rating_scale',NULL,0,'2026-07-13 00:35:34','2026-07-13 00:35:34'),(69,11,'Head saya secara efektif mampu menyelaraskan pekerjaan team dengan strategi dan tujuan organisasi yang lebih besar.','rating_scale',NULL,1,'2026-07-13 00:35:40','2026-07-13 00:35:40'),(70,11,'Head saya secara konsisten mengkomunikasikan informasi penting, keputusan, dan perubahan yang berdampak terhadap pekerjaan saya.','rating_scale',NULL,2,'2026-07-13 00:35:46','2026-07-13 00:35:46'),(71,11,'Head saya secara efektif mengambil keputusan tepat waktu dan bertanggung jawab atas hasil kerja tim.','rating_scale',NULL,3,'2026-07-13 00:35:53','2026-07-13 00:35:53'),(72,11,'Head saya secara proaktif mendukung saya dalam mengatasi tantangan dan hambatan yang mempengaruhi kinerja saya.','rating_scale',NULL,4,'2026-07-13 00:36:11','2026-07-13 00:36:11'),(73,11,'Head saya secara efektif mendelegasikan tanggung jawab, menunjukkan kepercayaan pada tim, dan secara aktif mendukung pertumbuhan individu.','rating_scale',NULL,5,'2026-07-13 00:36:23','2026-07-13 00:36:23'),(74,11,'Head saya menciptakan lingkungan yang penuh hormat, inklusif, dan aman secara psikologis di mana anggota tim merasa nyaman untuk menyampaikan pendapat dan memberikan ide.','rating_scale',NULL,6,'2026-07-13 00:36:45','2026-07-13 00:36:45'),(75,11,'Menurut Anda, apa kekuatan kepemimpinan utama yang dimiliki oleh atasan Anda?','text',NULL,7,'2026-07-13 00:36:51','2026-07-13 00:36:51'),(76,11,'Apa saran atau area pengembangan yang dapat membantu atasan Anda meningkatkan efektivitas tim dan mendukung keberhasilan anggota tim?','text',NULL,8,'2026-07-13 00:36:56','2026-07-13 00:36:56');
