--
-- Table structure for table `review_assignments`
--

DROP TABLE IF EXISTS `review_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `review_assignments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `review_cycle_id` bigint(20) unsigned NOT NULL,
  `reviewer_id` bigint(20) unsigned NOT NULL,
  `reviewee_id` bigint(20) unsigned NOT NULL,
  `review_type` enum('self','peer','upward','downward') NOT NULL,
  `status` enum('pending','in_progress','submitted') NOT NULL DEFAULT 'pending',
  `submitted_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `review_assignments_unique` (`review_cycle_id`,`reviewer_id`,`reviewee_id`,`review_type`),
  KEY `review_assignments_reviewer_id_foreign` (`reviewer_id`),
  KEY `review_assignments_reviewee_id_foreign` (`reviewee_id`),
  CONSTRAINT `review_assignments_review_cycle_id_foreign` FOREIGN KEY (`review_cycle_id`) REFERENCES `review_cycles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `review_assignments_reviewee_id_foreign` FOREIGN KEY (`reviewee_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `review_assignments_reviewer_id_foreign` FOREIGN KEY (`reviewer_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

